create extension if not exists postgis;
create table if not exists freebies(id uuid primary key default gen_random_uuid(),title text not null,description text,category text not null,venue text,address text,location geography(point,4326) not null,starts_at timestamptz,ends_at timestamptz,expires_at timestamptz,free_type text not null default 'free' check(free_type in ('free','signup')),requirements text,source_name text,source_url text,source_id text,verification_status text not null default 'unverified',confidence numeric default .5,last_verified_at timestamptz,image_url text,is_featured boolean not null default false,created_at timestamptz default now(),updated_at timestamptz default now(),unique(source_name,source_id));
create index if not exists freebies_location_idx on freebies using gist(location);
create table if not exists submissions(id uuid primary key default gen_random_uuid(),title text not null,venue text not null,category text,source_url text,description text,address text,latitude double precision,longitude double precision,starts_at timestamptz,ends_at timestamptz,requirements text,submitter_email text,status text default 'pending',created_at timestamptz default now());
alter table freebies enable row level security;alter table submissions enable row level security;
drop policy if exists "public_read_verified_freebies" on freebies;create policy "public_read_verified_freebies" on freebies for select to anon,authenticated using(verification_status='verified' and(expires_at is null or expires_at>now()));
drop policy if exists "public_submit_freebies" on submissions;create policy "public_submit_freebies" on submissions for insert to anon,authenticated with check(status='pending');
drop function if exists nearby_freebies(double precision,double precision,double precision);
create function nearby_freebies(user_lat double precision,user_lng double precision,radius_miles double precision default 25) returns table(id uuid,title text,description text,category text,venue text,address text,distance_miles double precision,starts_at timestamptz,ends_at timestamptz,free_type text,requirements text,source_url text,source_name text,image_url text,verification_status text,last_verified_at timestamptz,is_featured boolean) language sql stable set search_path='' as $$select f.id,f.title,f.description,f.category,f.venue,f.address,public.st_distance(f.location,public.st_setsrid(public.st_makepoint(user_lng,user_lat),4326)::public.geography)/1609.344,f.starts_at,f.ends_at,f.free_type,f.requirements,f.source_url,f.source_name,f.image_url,f.verification_status,f.last_verified_at,f.is_featured from public.freebies f where public.st_dwithin(f.location,public.st_setsrid(public.st_makepoint(user_lng,user_lat),4326)::public.geography,radius_miles*1609.344) and f.verification_status='verified' and(f.expires_at is null or f.expires_at>now()) order by f.is_featured desc,public.st_distance(f.location,public.st_setsrid(public.st_makepoint(user_lng,user_lat),4326)::public.geography) limit 200;$$;